{&quot;cells&quot;:[{&quot;cell_type&quot;:&quot;code&quot;,&quot;source&quot;:[&quot;content = \&quot;\&quot;\&quot;# ANEXO TÉCNICO - COMANDOS FORENSES
&quot;,&quot;
&quot;,&quot;**Analista:** Andrea Zabala Carcamo
&quot;,&quot;**Fecha:** 6 de junio de 2026
&quot;,&quot;**Sistema:** Linux Ubuntu 24.04
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 1. EXTRACCIÓN DE IMÁGENES&quot;],&quot;outputs&quot;:[],&quot;execution_count&quot;:null,&quot;metadata&quot;:{&quot;id&quot;:&quot;8pq2e8iT2HpY&quot;}},{&quot;cell_type&quot;:&quot;markdown&quot;,&quot;source&quot;:[&quot;```text
&quot;,&quot;ANEXO_COMANDOS_TECNICOS.md
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;for f in *.pdf; do
&quot;,&quot;    pdfimages -png \&quot;$f\&quot; \&quot;${f%.pdf}_img\&quot;
&quot;,&quot;done
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 2. DETECCIÓN DE PÁGINAS EN BLANCO
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;for img in *.png; do
&quot;,&quot;    media=$(identify -format \&quot;%[mean]\&quot; \&quot;$img\&quot; 2&gt;/dev/null)
&quot;,&quot;    [ \&quot;$media\&quot; = \&quot;65535\&quot; ] &amp;&amp; echo \&quot;PAGINA EN BLANCO: $img\&quot;
&quot;,&quot;done
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 3. ANÁLISIS COLOR VS B/N
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;for img in *_img-*.png; do
&quot;,&quot;    colorspace=$(identify -format \&quot;%[colorspace]\&quot; \&quot;$img\&quot; 2&gt;/dev/null)
&quot;,&quot;    if echo \&quot;$colorspace\&quot; | grep -qi \&quot;gray\&quot;; then
&quot;,&quot;        echo \&quot;BN: $img\&quot;
&quot;,&quot;    else
&quot;,&quot;        echo \&quot;COLOR: $img\&quot;
&quot;,&quot;    fi
&quot;,&quot;done
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 4. DETECCIÓN DE IMÁGENES DUPLICADAS
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;sha256sum *_img-*.png | sort | awk '{
&quot;,&quot;    hash=$1; file=$2;
&quot;,&quot;    if(prev_hash==hash &amp;&amp; file!=prev_file)
&quot;,&quot;        print \&quot;DUPLICADO: \&quot; hash \&quot; en \&quot; prev_file \&quot; y \&quot; file;
&quot;,&quot;    prev_hash=hash; prev_file=file
&quot;,&quot;}'
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 5. ANÁLISIS ESTRUCTURAL CON QPDF
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;qpdf --qdf --object-streams=disable archivo.pdf archivo_descomprimido.pdf
&quot;,&quot;qpdf --check archivo.pdf
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 6. CONTAR OBJETOS XOBJECT Y DEVICEGRAY
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;qpdf --qdf --object-streams=disable \&quot;$archivo\&quot; temp.qdf 2&gt;/dev/null
&quot;,&quot;xobj=$(grep -c \&quot;/XObject\&quot; temp.qdf 2&gt;/dev/null)
&quot;,&quot;gray=$(grep -c \&quot;/DeviceGray\&quot; temp.qdf 2&gt;/dev/null)
&quot;,&quot;echo \&quot;XObject: $xobj, DeviceGray: $gray\&quot;
&quot;,&quot;rm -f temp.qdf
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 7. ANÁLISIS CON PEEPDF
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;peepdf -f archivo.pdf
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 8. EXTRACCIÓN DE METADATOS
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;exiftool -a -G1 archivo.pdf
&quot;,&quot;pdfinfo archivo.pdf | grep -E \&quot;Creator|Producer|CreationDate\&quot;
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 9. COMPARACIÓN DE HASHES SHA256
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;sha256sum archivo.pdf
&quot;,&quot;
&quot;,&quot;for v in V_1junio V_2junio V_3junio V_4junio; do
&quot;,&quot;    echo \&quot;=== $v ===\&quot;
&quot;,&quot;    sha256sum \&quot;$v\&quot;/*.pdf | head -5
&quot;,&quot;done
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 10. VERIFICACIÓN DE CÓDIGOS QR
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;zbarimg archivo.pdf
&quot;,&quot;zbarimg archivo.pdf 2&gt;/dev/null | wc -l
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 11. ANÁLISIS DE PROPIEDADES DE IMAGEN
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;identify -format \&quot;%wx%h | %m | %[colorspace] | %[mean] | %[standard-deviation]\&quot; imagen.png
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 12. LISTADO COMPLETO DE XOBJECT POR VERSIÓN
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;for v in V_1junio V_2junio V_3junio V_4junio; do
&quot;,&quot;    echo \&quot;========== $v ==========\&quot;
&quot;,&quot;    for archivo in \&quot;$v\&quot;/*.pdf; do
&quot;,&quot;        [ -f \&quot;$archivo\&quot; ] || continue
&quot;,&quot;        nombre=$(basename \&quot;$archivo\&quot;)
&quot;,&quot;        temp_qdf=\&quot;temp_$$.qdf\&quot;
&quot;,&quot;        qpdf --qdf --object-streams=disable \&quot;$archivo\&quot; \&quot;$temp_qdf\&quot; 2&gt;/dev/null
&quot;,&quot;        xobj=$(grep -c \&quot;/XObject\&quot; \&quot;$temp_qdf\&quot; 2&gt;/dev/null)
&quot;,&quot;        gray=$(grep -c \&quot;/DeviceGray\&quot; \&quot;$temp_qdf\&quot; 2&gt;/dev/null)
&quot;,&quot;        rm -f \&quot;$temp_qdf\&quot;
&quot;,&quot;        echo \&quot;$nombre: XObject=$xobj, DeviceGray=$gray\&quot;
&quot;,&quot;    done
&quot;,&quot;done
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## 13. VERIFICACIÓN DE PROPORCIÓN DE PESOS
&quot;,&quot;
&quot;,&quot;```bash
&quot;,&quot;real=$(ls -S *.png | head -1)
&quot;,&quot;blanca=$(ls -S *.png | tail -1)
&quot;,&quot;
&quot;,&quot;echo \&quot;Imagen real:\&quot;
&quot;,&quot;identify -format \&quot;Dimensiones: %wx%h\nPeso: %b\nMedia: %[mean]\n\&quot; \&quot;$real\&quot;
&quot;,&quot;
&quot;,&quot;echo \&quot;Imagen blanca:\&quot;
&quot;,&quot;identify -format \&quot;Dimensiones: %wx%h\nPeso: %b\nMedia: %[mean]\n\&quot; \&quot;$blanca\&quot;
&quot;,&quot;
&quot;,&quot;```
&quot;,&quot;
&quot;,&quot;---
&quot;,&quot;
&quot;,&quot;## HERRAMIENTAS UTILIZADAS
&quot;,&quot;
&quot;,&quot;| Herramienta | Función |
&quot;,&quot;| --- | --- |
&quot;,&quot;| pdfimages | Extracción de imágenes |
&quot;,&quot;| ImageMagick (identify) | Análisis de propiedades |
&quot;,&quot;| sha256sum | Hash SHA-256 |
&quot;,&quot;| QPDF | Descompresión estructural |
&quot;,&quot;| peepdf | Análisis de estructura |
&quot;,&quot;| ExifTool | Extracción de metadatos |
&quot;,&quot;| zbarimg | Lectura de QR |
&quot;,&quot;
&quot;,&quot;---
